		WALK_LEFT = 2'b00,
		WALK_RIGHT = 2'b01,
		AAAH = 2'b10;

	always @(posedge clk or posedge areset) begin
		if (areset) begin
			state <= WALK_LEFT;
		end else begin
			case (state)
				WALK_LEFT: begin
					if (ground) begin
						if (bump_left) begin
							state <= WALK_RIGHT;
						end else begin
							state <= WALK_LEFT;
						end
					end else begin
						state <= AAAH;
					end
				end
				WALK_RIGHT: begin
					if (ground) begin
						if (bump_right) begin
							state <= WALK_LEFT;
						end else begin
							state <= WALK_RIGHT;
						end
					end else begin
						state <= AAAH;
					end
				end
				AAAH: begin
					if (ground) begin
						state <= WALK_LEFT;
					end else begin
						state <= AAAH;
					end
				end
			endcase
		end
	end

	assign walk_left = (state == WALK_LEFT);
	assign walk_right = (state == WALK_RIGHT);
	assign aaah = (state == AAAH);

endmodule

